def circuit_closed(record):
    """未配置熔断器或熔断状态为 C 的后端才参与调度。"""
    circuit = record["circuit"]
    return circuit is None or circuit["state"] == "C"


def drain_available(record):
    """仅 A（可用）态后端参与 pick/open 与新的 route 映射。"""
    return record["drain"]["state"] == "A"


